package com.forgedprogression.client;

import net.minecraft.client.renderer.texture.AbstractTexture;
import net.minecraft.client.renderer.texture.TextureUtil;
import net.minecraft.client.resources.IResourceManager;

import java.io.IOException;

/** Standalone texture (armor worn on the player) generated by recoloring a vanilla armor layer. Re-runs on resource reload. */
public class RecoloredTexture extends AbstractTexture {

    private final Recolor.Spec spec;

    public RecoloredTexture(Recolor.Spec spec) {
        this.spec = spec;
    }

    @Override
    public void loadTexture(IResourceManager manager) throws IOException {
        deleteGlTexture();
        TextureUtil.uploadTextureImageAllocate(getGlTextureId(), spec.render(manager), false, false);
    }
}
